html:
{%- set QMS_REF = "HR000.00" -%}
{%- set QMS_VERSION = "01-2026" -%}
{%- set QMS_EFFECTIVE = "01/08/2026" -%}

<div class="gate-pass">
	<table class="gp-head">
		<tr>
			<td class="gp-org">
				<div class="gp-company">{{ doc.company or "" }}</div>
				<div class="gp-title">EMPLOYEE GATE PASS FORM</div>
			</td>
			<td class="gp-qms">
				<div>Ref No: {{ QMS_REF }}</div>
				<div>Version No: {{ QMS_VERSION }}</div>
				<div>Effective Date: {{ QMS_EFFECTIVE }}</div>
			</td>
		</tr>
	</table>

	<table class="gp-body">
		<tr>
			<td class="gp-label">Employee Name</td>
			<td class="gp-value">{{ doc.employee_name or "" }}</td>
			<td class="gp-label">Payroll No</td>
			<td class="gp-value">{{ doc.payroll_no or "" }}</td>
		</tr>
		<tr>
			<td class="gp-label">Department</td>
			<td class="gp-value">{{ doc.department or "" }}</td>
			<td class="gp-label">Designation</td>
			<td class="gp-value">{{ doc.designation or "" }}</td>
		</tr>
		<tr>
			<td class="gp-label">Date</td>
			<td class="gp-value">{{ frappe.utils.formatdate(doc.date) if doc.date else "" }}</td>
			<td class="gp-label">Pass Type</td>
			<td class="gp-value">{{ doc.pass_type or "" }}</td>
		</tr>
		<tr>
			<td class="gp-label">Time Out</td>
			<td class="gp-value">{{ frappe.utils.format_time(doc.time_out) if doc.time_out else "" }}</td>
			<td class="gp-label">Time Back In</td>
			<td class="gp-value">{{ frappe.utils.format_time(doc.expected_time_in) if doc.expected_time_in else "Not returning same day" }}</td>
		</tr>
		<tr>
			<td class="gp-label">Reason for Leaving</td>
			<td class="gp-value" colspan="3">{{ doc.reason or "" }}</td>
		</tr>
	</table>

	<div class="gp-section">Approvals</div>
	<table class="gp-approvals">
		<thead>
			<tr>
				<th style="width: 30%">Stage</th>
				<th style="width: 40%">Name</th>
				<th style="width: 30%">Approved On</th>
			</tr>
		</thead>
		<tbody>
			<tr>
				<td>Employee</td>
				<td>{{ doc.employee_name or "" }}</td>
				<td>{{ frappe.utils.format_datetime(doc.creation) if doc.creation else "" }}</td>
			</tr>
			<tr>
				<td>Immediate Supervisor</td>
				<td>{{ doc.supervisor_name or doc.supervisor or "" }}</td>
				<td>{{ frappe.utils.format_datetime(doc.supervisor_action_on) if doc.supervisor_action_on else "" }}</td>
			</tr>
			<tr>
				<td>Head of Department</td>
				<td>{{ doc.hod_name or doc.hod or "" }}</td>
				<td>{{ frappe.utils.format_datetime(doc.hod_action_on) if doc.hod_action_on else "" }}</td>
			</tr>
			<tr>
				<td>Human Resource Dept</td>
				<td>{{ doc.hr_approver_name or doc.hr_approver or "" }}</td>
				<td>{{ frappe.utils.format_datetime(doc.hr_action_on) if doc.hr_action_on else "" }}</td>
			</tr>
		</tbody>
	</table>
	<div class="gp-note">
		System-approved. Approval timestamps constitute authorisation; no wet signature required.
	</div>

	<div class="gp-section">Gate Record</div>
	<table class="gp-body">
		<tr>
			<td class="gp-label">Actual Time Out</td>
			<td class="gp-box">{{ frappe.utils.format_time(doc.actual_time_out) if doc.actual_time_out else "&nbsp;" }}</td>
			<td class="gp-label">Actual Time In</td>
			<td class="gp-box">{{ frappe.utils.format_time(doc.actual_time_in) if doc.actual_time_in else "&nbsp;" }}</td>
		</tr>
		<tr>
			<td class="gp-label">Gate Officer</td>
			<td class="gp-box" colspan="3">{{ doc.gate_officer or "&nbsp;" }}</td>
		</tr>
	</table>

	<div class="gp-footer">{{ doc.name }}</div>
</div>

<style>
	.gate-pass {
		font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
		font-size: 11px;
		color: #000;
	}
	.gate-pass table {
		width: 100%;
		border-collapse: collapse;
		margin-bottom: 8px;
	}
	.gp-head td {
		vertical-align: top;
		padding-bottom: 6px;
		border-bottom: 2px solid #000;
	}
	.gp-company {
		font-size: 15px;
		font-weight: bold;
		text-transform: uppercase;
	}
	.gp-title {
		font-size: 12px;
		font-weight: bold;
		letter-spacing: 0.5px;
		margin-top: 2px;
	}
	.gp-qms {
		text-align: right;
		font-size: 10px;
		white-space: nowrap;
	}
	.gp-body td {
		padding: 5px 4px;
		vertical-align: bottom;
	}
	.gp-label {
		width: 18%;
		font-weight: bold;
		white-space: nowrap;
	}
	.gp-value {
		border-bottom: 1px dotted #000;
	}
	.gp-box {
		border: 1px solid #000;
		height: 28px;
	}
	.gp-section {
		font-weight: bold;
		text-transform: uppercase;
		font-size: 10px;
		letter-spacing: 0.5px;
		border-bottom: 1px solid #000;
		margin: 10px 0 6px;
		padding-bottom: 2px;
	}
	.gp-approvals th,
	.gp-approvals td {
		border: 1px solid #000;
		padding: 5px 6px;
		text-align: left;
	}
	.gp-approvals th {
		background: #eee;
		font-size: 10px;
		text-transform: uppercase;
	}
	.gp-note {
		font-size: 9px;
		font-style: italic;
		margin-top: -4px;
	}
	.gp-footer {
		margin-top: 10px;
		font-size: 9px;
		text-align: right;
		color: #444;
	}
</style>
